import{H as e,gt as t,nt as n,tt as r}from"./chunks/framework.sms2Rnvf.js";import"./chunks/assets.CKUgKlCM.js";var i=JSON.parse(`{"title":"Templates","description":"","frontmatter":{},"headers":[],"relativePath":"finding-templates/overview.md","filePath":"finding-templates/overview.md","lastUpdated":1781102819000}`),a={name:`finding-templates/overview.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /finding-templates/overview.md for this page in Markdown format</div><h1 id="templates" tabindex="-1">Templates <a class="header-anchor" href="#templates" aria-label="Permalink to “Templates”">​</a></h1><p>Templates are blueprints for findings. They contain common description texts for findings and vulnerabilities. Describe your finding texts once in a template and reuse them in multiple pentest reports. When writing a report, you just have to adapt the pentest specific details and add some screenshots.</p><h2 id="create-a-template" tabindex="-1">Create a template <a class="header-anchor" href="#create-a-template" aria-label="Permalink to “Create a template”">​</a></h2><p>The template library is managed in the <code>Templates</code> section of the navigation bar. Every user is able to view and use all templates. Only users with the <code>is_template_editor</code> permission can create, edit and delete templates.</p><p>You can either create a new empty template by clicking &quot;Create&quot;, or from a finding an existing report:</p><p><img src="/images/template_from_finding.gif" alt="Create template from finding" width="998" height="623"></p><h2 id="template-fields" tabindex="-1">Template fields <a class="header-anchor" href="#template-fields" aria-label="Permalink to “Template fields”">​</a></h2><p>The fields available in templates are the same as in findings. The template field definition is created from the finding fields of all global designs and predefined finding fields (e.g. title, cvss, description, recommendation, impact, summary, etc.).</p><p>This ensures that templates are independent of designs and templates can be used in projects of any design. Each design can define custom fields (additionally to a set of predefined fields). These custom fields are available in templates.</p><p>Some fields might not be relevant when creating templates because they are only relevant for findings in a specific design or contain project-specific settings. You can hide these fields in the template editor to focus on the relevant fields.</p><p><img src="/images/template_fields.png" alt="Template Fields" width="834" height="589"></p><p>Markdown fields allow pasting images from your clipboard:</p><p><img src="/images/images_in_templates.gif" alt="Paste image to markdown field" width="843" height="396"></p>`,14)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};